/**
 * Batch Apex class that flags open, past-due invoices as Overdue every night.
 *              Queries FB_Invoice__c records that are Open and past their Due_Date__c,
 *              sets their Status__c to Overdue (best-effort per record), and writes a single
 *              FB_Job_Summary__c carrying the run totals.
 *              Implements Database.Stateful so the running totals accumulate across chunks.
 *
 * @example
 * // Execute with the default batch size
 * Id jobId = OverdueInvoiceBatch.run();
 *
 * // Execute with a custom batch size
 * Database.executeBatch(new OverdueInvoiceBatch(), 100);
 */
public with sharing class OverdueInvoiceBatch implements Database.Batchable<FB_Invoice__c>, Database.Stateful {

    // ─── Constants ───────────────────────────────────────────────────────
    private static final Integer DEFAULT_BATCH_SIZE = 200;
    private static final String JOB_NAME = 'OverdueInvoiceBatch';
    private static final String STATUS_OPEN = 'Open';
    private static final String STATUS_OVERDUE = 'Overdue';

    // ─── Stateful Tracking ───────────────────────────────────────────────
    private Integer updatedCount = 0;
    private Integer failedCount = 0;
    private Decimal overdueAmount = 0;

    // ─── Constructor ─────────────────────────────────────────────────────

    /**
     * No-argument constructor required for batch execution.
     */
    public OverdueInvoiceBatch() {
        // Stateful fields default to zero and accumulate across chunks.
    }

    // ─── Batchable Interface ─────────────────────────────────────────────

    /**
     * Defines the scope of records to process.
     *              Returns a QueryLocator over open invoices whose due date is before today.
     * @param bc The batch context (unused; supports direct invocation with null)
     * @return QueryLocator over the candidate overdue invoices
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        String soql =
            'SELECT Id, Name, Status__c, Due_Date__c, Amount__c, Customer_Email__c ' +
            'FROM FB_Invoice__c ' +
            'WHERE Status__c = \'' + STATUS_OPEN + '\' AND Due_Date__c < TODAY ' +
            'ORDER BY Id';
        return Database.getQueryLocator(soql);
    }

    /**
     * Marks each invoice in the chunk as Overdue and accumulates the run totals.
     *              Uses Database.update with allOrNone=false so a record that fails to save
     *              (for example, blocked by a validation rule) does not prevent the rest of
     *              the chunk from being saved.
     * @param bc The batch context (unused; supports direct invocation with null)
     * @param scope List of FB_Invoice__c records in the current batch
     */
    public void execute(Database.BatchableContext bc, List<FB_Invoice__c> scope) {
        if (scope == null || scope.isEmpty()) {
            return;
        }

        // Keep the amounts keyed by Id so successful saves can be summed.
        Map<Id, FB_Invoice__c> invoicesById = new Map<Id, FB_Invoice__c>(scope);

        for (FB_Invoice__c invoice : scope) {
            invoice.Status__c = STATUS_OVERDUE;
        }

        // allOrNone=false -> partial success; one bad record cannot abort the chunk.
        List<Database.SaveResult> results = Database.update(scope, false);
        processResults(results, invoicesById);
    }

    /**
     * Inserts exactly one FB_Job_Summary__c carrying the accumulated run totals.
     * @param bc The batch context (unused; supports direct invocation with null)
     */
    public void finish(Database.BatchableContext bc) {
        FB_Job_Summary__c summary = new FB_Job_Summary__c(
            Job_Name__c = JOB_NAME,
            Records_Updated__c = updatedCount,
            Records_Failed__c = failedCount,
            Overdue_Amount__c = overdueAmount
        );
        insert summary;
    }

    // ─── Private Helpers ─────────────────────────────────────────────────

    /**
     * Walks the partial-success results, tracking successes and failures and summing the
     * Amount__c of every invoice that was updated (blank amounts count as 0).
     * @param results List of Database.SaveResult from the update operation
     * @param invoicesById Map of invoice Id to record for amount lookups
     */
    private void processResults(List<Database.SaveResult> results, Map<Id, FB_Invoice__c> invoicesById) {
        for (Database.SaveResult result : results) {
            if (result.isSuccess()) {
                updatedCount++;
                FB_Invoice__c invoice = invoicesById.get(result.getId());
                if (invoice != null && invoice.Amount__c != null) {
                    overdueAmount += invoice.Amount__c;
                }
            } else {
                failedCount++;
            }
        }
    }

    // ─── Static Helpers ──────────────────────────────────────────────────

    /**
     * Convenience method to execute the batch with the default batch size.
     * @return The batch job Id
     */
    public static Id run() {
        return Database.executeBatch(new OverdueInvoiceBatch(), DEFAULT_BATCH_SIZE);
    }
}
