/**
 * Bulk-safe handler for the Contact trigger.
 *
 * Behaviour preserved exactly from the original trigger:
 *  - Before insert/update: MailingCountry is defaulted from the parent Account's
 *    BillingCountry, and (insert only) LeadSource is defaulted from the parent
 *    Account's AccountSource, whenever the Contact fields are blank.
 *  - After insert: when a new Contact has a Phone and its Account has none, the
 *    first such Contact in trigger order sets the Account phone.
 *
 * Governor budget: one trigger execution of up to 200 Contacts issues at most
 * 2 SOQL queries (one per context) and at most 1 DML statement (bulk Account update).
 */
public with sharing class ContactTriggerHandler {

    /**
     * Routes the current trigger context to the appropriate handler method.
     */
    public static void handle() {
        if (Trigger.isBefore && (Trigger.isInsert || Trigger.isUpdate)) {
            handleBefore();
        }
        if (Trigger.isAfter && Trigger.isInsert) {
            handleAfterInsert();
        }
    }

    /**
     * Before insert/update: applies Account defaults to Contacts that are linked
     * to an Account and have a blank target field.
     *
     * Issues a single SOQL query for all distinct AccountIds in the batch.
     */
    private static void handleBefore() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
                [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]);

        for (Contact c : Trigger.new) {
            if (c.AccountId == null) {
                continue;
            }
            Account account = accountsById.get(c.AccountId);
            if (account == null) {
                // Original code executed a per-record single-row query that
                // failed when no Account matched; preserve the fail-fast behaviour.
                throw new Exception('Account not found for Contact AccountId: ' + c.Id);
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = account.BillingCountry;
            }
            if (Trigger.isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = account.AccountSource;
            }
        }
    }

    /**
     * After insert: copies the Phone of the first new Contact in trigger order
     * onto Accounts that do not have a Phone yet.
     *
     * Issues a single SOQL query and a single bulk DML statement, regardless of
     * how many Contacts are in the batch.
     */
    private static void handleAfterInsert() {
        // Keep only the first Contact per Account (in trigger order) that has a
        // Phone, matching the original loop where the first matching Contact
        // populated the Account and later Contacts saw the Account already set.
        Map<Id, Contact> firstContactWithPhoneByAccountId = new Map<Id, Contact>();
        for (Contact c : Trigger.new) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            if (!firstContactWithPhoneByAccountId.containsKey(c.AccountId)) {
                firstContactWithPhoneByAccountId.put(c.AccountId, c);
            }
        }
        if (firstContactWithPhoneByAccountId.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
                [SELECT Id, Phone FROM Account WHERE Id IN :firstContactWithPhoneByAccountId.keySet()]);

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : firstContactWithPhoneByAccountId.keySet()) {
            Account account = accountsById.get(accountId);
            if (account == null) {
                throw new Exception('Account not found for Contact AccountId: ' + accountId);
            }
            if (String.isBlank(account.Phone)) {
                account.Phone = firstContactWithPhoneByAccountId.get(accountId).Phone;
                accountsToUpdate.add(account);
            }
        }
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
