/**
 * Bulk-safe handler for the Contact trigger. Collapses per-record SOQL into a
 * single query per trigger context and per-record DML into one statement,
 * while preserving the original business behaviour exactly.
 */
public with sharing class ContactTriggerHandler {

    /**
     * Entry point invoked by ContactTrigger.
     * @param newRecords the Contact records being inserted or updated
     * @param isInsert true when the trigger context is an insert
     * @param isBefore true when the trigger context is before
     */
    public static void handle(List<Contact> newRecords, Boolean isInsert, Boolean isBefore) {
        if (newRecords == null || newRecords.isEmpty()) {
            return;
        }
        if (isBefore) {
            handleBefore(newRecords, isInsert);
        }
        if (!isBefore && isInsert) {
            handleAfterInsert(newRecords);
        }
    }

    /**
     * Populates blank MailingCountry and LeadSource from the parent Account.
     * @param contacts the new Contact records
     * @param isInsert true when the trigger context is an insert
     */
    private static void handleBefore(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * Copies the phone from the first new Contact (in trigger order) to a parent
     * Account that has no phone. Mutating the shared in-memory Account guarantees
     * that only the first contact in trigger order wins.
     * @param contacts the new Contact records
     */
    private static void handleAfterInsert(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        List<Account> accountsToUpdate = new List<Account>();
        for (Contact c : contacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
