/**
 * On-demand account re-rating job.
 *
 * Each execution processes at most 200 accounts (the first 200 Ids of its
 * list) with exactly one SOQL query and one DML statement, setting Rating
 * from AnnualRevenue. When Ids remain, the execution enqueues a new
 * AccountScoringJob for the remainder, so executions form a chain that
 * covers the entire input list (up to 50,000 accounts).
 */
public with sharing class AccountScoringJob implements Queueable {

    /** Maximum number of accounts processed by a single job execution. */
    private static final Integer CHUNK_SIZE = 200;

    /** AnnualRevenue threshold (inclusive) for a Hot rating. */
    private static final Decimal HOT_REVENUE_THRESHOLD = 1000000;

    /** AnnualRevenue threshold (inclusive) for a Warm rating. */
    private static final Decimal WARM_REVENUE_THRESHOLD = 100000;

    /** Rating for AnnualRevenue >= HOT_REVENUE_THRESHOLD. */
    private static final String RATING_HOT = 'Hot';

    /** Rating for AnnualRevenue >= WARM_REVENUE_THRESHOLD. */
    private static final String RATING_WARM = 'Warm';

    /** Rating for anything below WARM_REVENUE_THRESHOLD, including blank. */
    private static final String RATING_COLD = 'Cold';

    /** Ids of the accounts this job is responsible for re-rating. */
    private final List<Id> accountIds;

    /**
     * Creates a job that re-rates the given accounts.
     *
     * @param accountIds Ids of the accounts to re-rate; null or empty makes the job a no-op.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    /**
     * Enqueues the first job in the chain.
     *
     * @param accountIds Ids of the accounts to re-rate.
     * @return The AsyncApexJob Id of the first enqueued job, or null when the list is null or empty.
     * @example
     * Id jobId = AccountScoringJob.start(accountIds);
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    /**
     * Re-rates the first up to 200 accounts of this job's list (one SOQL
     * query and one DML statement), then enqueues a follow-up job for any
     * remaining Ids so the chain covers the full list.
     *
     * @param context The QueueableContext for this execution (unused).
     */
    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer chunkSize = Math.min(CHUNK_SIZE, accountIds.size());
        List<Id> chunk = accountIds.subList(0, chunkSize);

        // Single query per execution; WITH USER_MODE enforces the running user's FLS/CRUD.
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, AnnualRevenue FROM Account WHERE Id IN :chunk WITH USER_MODE]
        );

        List<Account> accountsToRate = new List<Account>(accountsById.values());
        for (Account account : accountsToRate) {
            account.Rating = calculateRating(account.AnnualRevenue);
        }

        if (!accountsToRate.isEmpty()) {
            // Single DML statement per execution; allOrNone=false so one bad record
            // cannot abort this execution and the rest of the chain.
            Database.update(accountsToRate, false);
        }

        if (chunkSize < accountIds.size()) {
            // Chain: the remainder is strictly shorter, so the chain always terminates.
            System.enqueueJob(new AccountScoringJob(accountIds.subList(chunkSize, accountIds.size())));
        }
    }

    /**
     * Maps AnnualRevenue to an account rating.
     *
     * @param annualRevenue The account's AnnualRevenue; may be null.
     * @return Hot for >= 1,000,000, Warm for >= 100,000, Cold for everything else including blank.
     */
    private static String calculateRating(Decimal annualRevenue) {
        if (annualRevenue != null && annualRevenue >= HOT_REVENUE_THRESHOLD) {
            return RATING_HOT;
        }
        if (annualRevenue != null && annualRevenue >= WARM_REVENUE_THRESHOLD) {
            return RATING_WARM;
        }
        return RATING_COLD;
    }
}
