/**
 * Re-rates Accounts (Hot/Warm/Cold) from AnnualRevenue in bulk, on demand.
 *
 * A single launch enqueues the first job of a chain; each execution processes
 * at most 200 accounts with one SOQL query and one DML statement, then
 * enqueues a follow-up job holding the remaining Ids. This keeps the job
 * safe for up to 50,000 accounts while staying within governor limits.
 */
public class AccountScoringJob implements Queueable {

    /** Maximum number of accounts processed per execution. */
    private static final Integer MAX_ACCOUNTS_PER_EXECUTION = 200;

    /** AnnualRevenue threshold (inclusive) for the Hot rating. */
    private static final Decimal HOT_REVENUE_THRESHOLD = 1000000;

    /** AnnualRevenue threshold (inclusive) for the Warm rating. */
    private static final Decimal WARM_REVENUE_THRESHOLD = 100000;

    private static final String RATING_HOT = 'Hot';
    private static final String RATING_WARM = 'Warm';
    private static final String RATING_COLD = 'Cold';

    /** Ids of the accounts still to be processed by this job and its chain. */
    private final List<Id> accountIds;

    /**
     * @param accountIds Ids of the accounts this job (and any chained jobs)
     *        should re-rate. May be null or empty; such a job is a no-op.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    /**
     * Enqueues the first job of the chain and returns its job Id.
     *
     * @param accountIds Ids of the accounts to re-rate
     * @return the job Id of the enqueued job, or null when the list is null or empty
     * @example
     * Id jobId = AccountScoringJob.start(allAccountIds);
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    /**
     * Processes the first up to 200 accounts of this job's list in a single
     * SOQL query and a single DML statement, then enqueues a follow-up job
     * with the remaining Ids when any remain. A null or empty id list makes
     * the execution a no-op.
     *
     * @param context QueueableContext supplied by the platform (unused)
     */
    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer batchSize = Math.min(MAX_ACCOUNTS_PER_EXECUTION, accountIds.size());
        List<Id> batchIds = new List<Id>(accountIds.subList(0, batchSize));

        // One SOQL query per execution, with USER_MODE for FLS enforcement.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
            ORDER BY Id
            LIMIT :MAX_ACCOUNTS_PER_EXECUTION
            WITH USER_MODE
        ];

        // One DML statement per execution (partial success).
        for (Account account : accounts) {
            account.Rating = calculateRating(account.AnnualRevenue);
        }
        if (!accounts.isEmpty()) {
            Database.update(accounts, AccessLevel.USER_MODE, false);
        }

        // Chain the remaining work; never skipped in test mode.
        List<Id> remainingIds = new List<Id>(accountIds.subList(batchSize, accountIds.size()));
        if (!remainingIds.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }

    /**
     * Maps AnnualRevenue to the standard Account Rating picklist.
     *
     * @param annualRevenue the account's AnnualRevenue (may be null)
     * @return Hot for 1,000,000 and above, Warm for 100,000 and above,
     *         Cold otherwise (including null/blank revenue)
     */
    private static String calculateRating(Decimal annualRevenue) {
        if (annualRevenue == null || annualRevenue < WARM_REVENUE_THRESHOLD) {
            return RATING_COLD;
        }
        if (annualRevenue >= HOT_REVENUE_THRESHOLD) {
            return RATING_HOT;
        }
        return RATING_WARM;
    }
}
