/**
 * Nightly scheduled job that purges aged integration log records from
 * FB_Integration_Log__c to keep data storage under control.
 *
 * Retention policy:
 * - Logs with Level__c blank or any value other than ERROR are deleted once
 *   they are more than 30 days old.
 * - Logs with Level__c = ERROR are retained until they are more than 180
 *   days old.
 *
 * If more than 50,000 records qualify in a single run (the SOQL result
 * limit), the remainder is removed on subsequent nightly runs.
 */
public with sharing class LogPurgeJob implements Schedulable {

    private static final String JOB_NAME = 'Log purge (nightly)';
    private static final String NIGHTLY_CRON = '0 0 2 * * ?';
    private static final String LEVEL_ERROR = 'ERROR';
    private static final Integer STANDARD_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final Integer DELETE_CHUNK_SIZE = 1000;

    /**
     * No-argument constructor required so the class can be instantiated
     * by System.schedule.
     */
    public LogPurgeJob() { }

    /**
     * Scheduler entry point. Deletes integration log records that have
     * passed their retention window. If the purge fails, the exception
     * propagates and the Apex job is marked Failed with the original
     * stack trace.
     */
    public void execute(SchedulableContext context) {
        purge();
    }

    /**
     * Deletes FB_Integration_Log__c records past their retention window:
     * non-ERROR (including blank) logs older than 30 days, and ERROR logs
     * older than 180 days. Queries are selective on CreatedDate and run
     * outside loops; DML is executed in bounded chunks of 1,000 records.
     *
     * @return the number of records deleted
     */
    public static Integer purge() {
        Date standardCutoff = Date.today().addDays(-STANDARD_RETENTION_DAYS);
        Date errorCutoff = Date.today().addDays(-ERROR_RETENTION_DAYS);

        List<Id> logIds = new List<Id>();

        // Standard logs (blank or non-ERROR) older than 30 days.
        logIds.addAll(collectIds(
            [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE CreatedDate < :standardCutoff
                AND (Level__c = NULL OR Level__c != :LEVEL_ERROR)
                WITH USER_MODE
            ]
        ));

        // ERROR logs older than 180 days.
        logIds.addAll(collectIds(
            [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE CreatedDate < :errorCutoff
                AND Level__c = :LEVEL_ERROR
                WITH USER_MODE
            ]
        ));

        Integer deletedCount = 0;
        for (Integer start = 0; start < logIds.size(); start += DELETE_CHUNK_SIZE) {
            List<Id> chunk = logIds.subList(
                start,
                Math.min(start + DELETE_CHUNK_SIZE, logIds.size())
            );
            delete chunk;
            deletedCount += chunk.size();
        }

        return deletedCount;
    }

    /**
     * Schedules the purge to run daily at 02:00 (org timezone) under the
     * job name "Log purge (nightly)".
     *
     * @return the Id of the CronTrigger returned by the scheduling call
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, NIGHTLY_CRON, new LogPurgeJob());
    }

    /**
     * Extracts Id values from a log query result.
     *
     * @param logs query result records
     * @return the Ids of the given records
     */
    private static List<Id> collectIds(List<FB_Integration_Log__c> logs) {
        List<Id> ids = new List<Id>();
        for (FB_Integration_Log__c log : logs) {
            ids.add(log.Id);
        }
        return ids;
    }
}
