```apex
/**
 * Nightly maintenance job that purges aged integration logs.
 *
 * Deletes {@code FB_Integration_Log__c} records created more than 30 days ago,
 * except records whose Level__c is 'ERROR'; error logs are kept until they are
 * more than 180 days old. Each run is bounded so a large backlog is drained
 * over successive nightly runs.
 */
public with sharing class LogPurgeJob implements Schedulable {

    /** Cron expression for a daily run at 02:00 in the org's time zone. */
    private static final String CRON_NIGHTLY = '0 0 2 * * ?';

    /** Name of the scheduled job, as shown in Apex job history. */
    private static final String JOB_NAME = 'Log purge (nightly)';

    /** Retention in days for log records whose Level__c is not 'ERROR'. */
    private static final Integer NON_ERROR_RETENTION_DAYS = 30;

    /** Retention in days for log records whose Level__c is 'ERROR'. */
    private static final Integer ERROR_RETENTION_DAYS = 180;

    /** Value of Level__c that marks a log as an error. */
    private static final String LEVEL_ERROR = 'ERROR';

    /** Maximum number of records purged in a single run (single SOQL/DML limit). */
    private static final Integer MAX_RECORDS_PER_RUN = 50000;

    /**
     * No-argument constructor required to instantiate the class from a schedule.
     */
    public LogPurgeJob() {
    }

    /**
     * Purges integration logs that are past their retention period.
     *
     * Records created more than 30 days ago are deleted, except records whose
     * Level__c is 'ERROR', which are kept until they are more than 180 days
     * old. A blank Level__c is treated as a non-error log. Runs are capped at
     * {@link MAX_RECORDS_PER_RUN} records so that a large backlog is drained
     * over successive nightly runs.
     */
    public void execute(SchedulableContext context) {
        Date nonErrorCutoff = Date.today().addDays(-NON_ERROR_RETENTION_DAYS);
        Date errorCutoff = Date.today().addDays(-ERROR_RETENTION_DAYS);

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WITH USER_MODE
            WHERE (CreatedDate < :nonErrorCutoff AND (Level__c = NULL OR Level__c != :LEVEL_ERROR))
               OR (CreatedDate < :errorCutoff AND Level__c = :LEVEL_ERROR)
            ORDER BY CreatedDate
            LIMIT :MAX_RECORDS_PER_RUN
        ];

        if (logsToDelete.isEmpty()) {
            return;
        }

        List<Database.SaveResult> deleteResults = Database.delete(logsToDelete, false);
        Integer failures = 0;
        for (Database.SaveResult deleteResult : deleteResults) {
            if (!deleteResult.isSuccess()) {
                failures++;
            }
        }

        if (failures > 0) {
            throw new Exception(
                'LogPurgeJob: ' + failures + ' of ' + logsToDelete.size() +
                ' integration log records could not be deleted. Review the Apex job history for details.'
            );
        }
    }

    /**
     * Schedules the purge to run every day at 02:00 in the org's time zone.
     *
     * @return The Id of the CronTrigger created by the schedule call
     * @example
     * Id cronId = LogPurgeJob.scheduleNightly();
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_NIGHTLY, new LogPurgeJob());
    }
}
