import { LightningElement, api } from 'lwc';
import FavoriteAddLabel from '@salesforce/label/c.Favorite_Add';
import FavoriteRemoveLabel from '@salesforce/label/c.Favorite_Remove';

export default class FavoriteToggle extends LightningElement {
    _favorite = false;

    /**
     * Whether the record is a favourite. Controlled by the parent:
     * the parent may change it at any time (e.g. after a server refresh)
     * and the button immediately reflects the new value.
     */
    @api
    get favorite() {
        return this._favorite;
    }
    set favorite(value) {
        const isFavorite = value === true || value === 'true';
        if (isFavorite !== this._favorite) {
            this._favorite = isFavorite;
        }
    }

    /**
     * Label of the action a click performs: the Remove label when the
     * record is a favourite, the Add label otherwise.
     */
    get actionLabel() {
        return this._favorite ? FavoriteRemoveLabel : FavoriteAddLabel;
    }

    get isPressed() {
        return this._favorite ? 'true' : 'false';
    }

    get iconName() {
        return this._favorite ? 'utility:heart' : 'utility:heart_off';
    }

    get iconClass() {
        return this._favorite ? 'slds-text-color_brand' : 'slds-text-color_weak';
    }

    /**
     * Flips the displayed state immediately (optimistic UI) and notifies
     * the parent via the `favoritechange` event with
     * `detail: { favorite: <new boolean value> }`.
     */
    handleClick() {
        this._favorite = !this._favorite;
        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                bubbles: true,
                composed: true,
                detail: { favorite: this._favorite }
            })
        );
    }
}
