import FAVORITE_ADD from '@salesforce/label/c.Favorite_Add';
import FAVORITE_REMOVE from '@salesforce/label/c.Favorite_Remove';

/**
 * Icon-style toggle button that marks a record as a favorite.
 *
 * State is controlled by the parent through the public `favorite`
 * property, which may be changed at any time (e.g. after a server
 * refresh); the button always renders that value. Clicking the
 * button flips the displayed state immediately (optimistic UI) and
 * dispatches a `favoritechange` event with the new value so the
 * parent can persist it.
 */
export default class FavoriteToggle extends LightningElement {
    /**
     * Whether the record is currently a favorite.
     * @type {Boolean}
     */
    @api favorite = false;

    get isFavorite() {
        return this.favorite === true;
    }

    /**
     * ARIA expects aria-pressed as the string values "true" or "false".
     */
    get ariaPressed() {
        return this.isFavorite ? 'true' : 'false';
    }

    /**
     * Label of the action a click performs: Remove when it is a
     * favorite, Add when it is not. Used for both aria-label and title.
     */
    get actionLabel() {
        return this.isFavorite ? FAVORITE_REMOVE : FAVORITE_ADD;
    }

    /**
     * Filled brand color when a favorite, muted gray otherwise.
     */
    get iconStyle() {
        return this.isFavorite
            ? 'color: var(--lwc-brandColor, #0b5cda);'
            : 'color: var(--lwc-gray-7, #545454);';
    }

    handleToggle() {
        this.favorite = !this.isFavorite;
        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                bubbles: true,
                composed: true,
                detail: { favorite: this.favorite }
            })
        );
    }
}
