import { LightningElement } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const FREE_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    /**
     * Keeps each field's current value from its change event.
     * @param {CustomEvent} event change event from a lightning-input
     */
    handleFieldChange(event) {
        const field = event.currentTarget.dataset.field;
        if (field) {
            this[field] = event.detail.value;
        }
    }

    /**
     * Validates every field at once (free-email policy included), then calls
     * RegistrationController.register imperatively and toasts the result.
     */
    handleRegister() {
        const emailInput = this.template.querySelector(
            'lightning-input[data-field="email"]'
        );

        // 1. Reject common free email providers as work email addresses.
        const domain = (this.email.split('@')[1] || '').toLowerCase();
        if (FREE_EMAIL_DOMAINS.includes(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // 2. Report validity on every input so all invalid fields show their
        //    messages at once, even when an earlier field is already invalid.
        const inputs = this.template.querySelectorAll('lightning-input[data-field]');
        inputs.forEach((input) => input.reportValidity());

        // 3. Stop if any input is still invalid.
        const hasInvalid = [...inputs].some((input) => !input.checkValidity());
        if (hasInvalid) {
            return;
        }

        // 4. Register imperatively and show a toast for the result.
        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        message: 'You are registered for the event.',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        message: error.body.message,
                        variant: 'error'
                    })
                );
            });
    }
}
