import { LightningElement } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const NON_WORK_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleFieldChange(event) {
        const field = event.target.dataset.field;
        this[field] = event.detail.value;
    }

    handleRegister() {
        // Step 1: enforce work-email rule before any validity reporting.
        const emailInput = this.template.querySelector('[data-field="email"]');
        if (NON_WORK_DOMAINS.includes(this.getEmailDomain())) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2: report validity on every input so all messages show at once.
        let hasInvalid = false;
        this.template.querySelectorAll('[data-field]').forEach((input) => {
            input.reportValidity();
            if (!input.checkValidity()) {
                hasInvalid = true;
            }
        });

        // Step 3: stop if anything is invalid.
        if (hasInvalid) {
            return;
        }

        // Step 4: call Apex imperatively and toast the outcome.
        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        variant: 'error',
                        message: error.body.message
                    })
                );
            });
    }

    getEmailDomain() {
        if (!this.email) {
            return '';
        }
        const index = this.email.lastIndexOf('@');
        if (index < 0) {
            return '';
        }
        return this.email.slice(index + 1).trim().toLowerCase();
    }
}
