    /**
     * Accessible name of the list, rendered as aria-label.
     * @type {string}
     */
    @api label;

    _options = [];

    /**
     * Options as an array of { value, label }.
     * @type {Array<{ value: string, label: string }>}
     */
    @api
    get options() {
        return this._options;
    }

    @api
    set options(newOptions) {
        this._options = (newOptions || []).map((option, index) => ({
            value: option.value,
            label: option.label,
            id: `${OPTION_ID_PREFIX}${this.instanceId}-${index}`
        }));
        this.syncActiveOption();
    }

    _value = '';

    /**
     * The selected value. May be changed by the parent at any time.
     * @type {string}
     */
    @api
    get value() {
        return this._value;
    }

    @api
    set value(newValue) {
        this._value = newValue ?? '';
        this.syncActiveOption();
    }

    /** Index of the active (referenced) option. */
    _activeIndex = 0;

    /** Id of the active option, used as aria-activedescendant. */
    get activeDescendant() {
        const option = this._options[this._activeIndex];
        return option ? option.id : null;
    }

    /**
     * Keeps the active option in sync with the selection:
     * the selected option, or the first option when nothing is selected.
     */
    syncActiveOption() {
        if (this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );
        this._activeIndex = selectedIndex >= 0 ? selectedIndex : 0;
    }

    /**
     * Keydown handler on the listbox.
     * preventDefault() is called for ArrowUp, ArrowDown, Home, End,
     * Enter and space only; every other key (notably Tab) keeps its
     * default behaviour.
     */
    handleKeydown(event) {
        if (this._options.length === 0) {
            return;
        }

        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                this.moveActiveOption(1);
                break;
            case 'ArrowUp':
                event.preventDefault();
                this.moveActiveOption(-1);
                break;
            case 'Home':
                event.preventDefault();
                this.setActiveOption(0);
                break;
            case 'End':
                event.preventDefault();
                this.setActiveOption(this._options.length - 1);
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this.selectActiveOption();
                break;
            default:
