import { LightningElement, api } from 'lwc';

/**
 * Accessible single-select listbox following the WAI-ARIA listbox pattern.
 *
 * DOM focus stays on the <ul role="listbox"> element (tabindex=0). The "active"
 * option is only referenced through aria-activedescendant (it is the option whose
 * id the listbox points at). Selection is a controlled value owned by the parent:
 * the parent can set `value` at any time and the component reflects it. Selecting
 * an option dispatches a `change` event with `detail: { value }` (unless the option
 * was already selected).
 *
 * Keyboard (handled on the listbox, via event.key):
 *  - ArrowDown / ArrowUp : move the active option by one (no wrap-around).
 *  - Home / End          : move the active option to the first / last option.
 *  - Enter / Space       : select the active option.
 *  - Only these six keys call preventDefault(); every other key (e.g. Tab) keeps
 *    its default behaviour.
 * Clicking an option selects it and makes it the active option.
 */
export default class StatusListbox extends LightningElement {
    /** Accessible name of the list (used as aria-label). */
    @api label;

    _options = [];
    _value;
    _activeIndex = 0;

    /** Array of { value, label } options. */
    @api
    get options() {
        return this._options;
    }

    @api
    set options(newOptions) {
        this._options = Array.isArray(newOptions) ? newOptions : [];
        this._syncActiveIndex();
    }

    /** The selected value (may be empty). The parent can change it at any time. */
    @api
    get value() {
        return this._value;
    }

    @api
    set value(newValue) {
        this._value = newValue;
        // When the parent changes the selection, the active option moves to it.
        this._syncActiveIndex();
    }

    /**
     * Options enriched with the per-option id and the rendered aria-selected
     * state ('true' / 'false'). Recomputed on every render so it always reflects
     * the current value and active index.
     */
    get displayOptions() {
        const value = this._value;
        return (this._options || []).map((option, index) => ({
            ...option,
            id: `statusListbox-option-${index}`,
            selected: option.value === value ? 'true' : 'false'
        }));
    }

    /** Id of the active option (the one referenced by aria-activedescendant). */
    get activeId() {
        const options = this.displayOptions;
        if (!options.length) {
            return '';
        }
        let index = this._activeIndex;
        if (index < 0) {
            index = 0;
        }
        if (index > options.length - 1) {
            index = options.length - 1;
        }
        return options[index].id;
    }

    /**
     * Keeps the active option in sync with the selection: the active option is the
     * selected option, or the first option when nothing is selected.
     */
    _syncActiveIndex() {
        const options = this._options || [];
        if (!options.length) {
            this._activeIndex = 0;
            return;
        }
        const index = options.findIndex((option) => option.value === this._value);
        this._activeIndex = index >= 0 ? index : 0;
    }

    handleKeydown(event) {
        const key = event.key;
        const length = (this._options || []).length;
        if (length === 0) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                event.preventDefault();
                if (this._activeIndex < length - 1) {
                    this._activeIndex += 1;
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (this._activeIndex > 0) {
                    this._activeIndex -= 1;
                }
                break;
            case 'Home':
                event.preventDefault();
                this._activeIndex = 0;
                break;
            case 'End':
                event.preventDefault();
                this._activeIndex = length - 1;
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectActive();
                break;
            default:
                // Every other key (notably Tab) keeps its default behaviour.
                break;
        }
    }

    handleClick(event) {
        const clickedValue = event.currentTarget.getAttribute('data-value');
        const options = this._options || [];
        const index = options.findIndex(
            (option) => String(option.value) === String(clickedValue)
        );
        if (index === -1) {
            return;
        }
        // Clicking selects the option and makes it the active option.
        this._activeIndex = index;
        this._selectActive();
    }

    /** Selects the active option and dispatches `change` unless already selected. */
    _selectActive() {
        const options = this._options || [];
        if (!options.length) {
            return;
        }
        let index = this._activeIndex;
        if (index < 0) {
            index = 0;
        }
        if (index > options.length - 1) {
            index = options.length - 1;
        }
        const option = options[index];
        if (!option) {
            return;
        }
        // Nothing is dispatched if the active option was already the selected one.
        if (option.value === this._value) {
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value },
                bubbles: true,
                composed: true
            })
        );
    }
}
